/*
 * #version 450
 * layout(local_size_x = 32) in;
 * layout(std430, binding = 0) buffer Data { float v[]; } data;
 * layout(push_constant) uniform P { float scale; } pc;
 * shared float sh[32];
 * struct Pair { float lo; float hi; };
 * Pair split(float x)
 * {
 *     Pair p;
 *     p.lo = fract(x);
 *     p.hi = floor(x);
 *     return p;
 * }
 * void accumulate(inout float acc, float x, out int sign_out)
 * {
 *     if (x < 0.0) {
 *         sign_out = -1;
 *         acc -= x;
 *         return;
 *     }
 *     sign_out = 1;
 *     acc += x * pc.scale;
 * }
 * float neighbor(uint i)
 * {
 *     return sh[(i + 1u) % 32u];
 * }
 * float process(uint i)
 * {
 *     float acc = 0.0;
 *     int s;
 *     Pair p = split(data.v[i]);
 *     accumulate(acc, p.lo, s);
 *     accumulate(acc, -p.hi, s);
 *     if (s > 0) {
 *         if (acc > 2.0) {
 *             return acc;
 *         } else if (acc < -2.0) {
 *             return -acc;
 *         }
 *     }
 *     return acc + float(s);
 * }
 * void main()
 * {
 *     uint i = gl_GlobalInvocationID.x;
 *     uint l = gl_LocalInvocationID.x;
 *     sh[l] = data.v[i];
 *     barrier();
 *     float n = neighbor(l);
 *     barrier();
 *     data.v[i] = process(i) + n;
 * }
 */
